#!/bin/bash
# OXIDE — fix agent crash during obfuscated sleep
# Applies all accumulated fixes: debug logging, body limit, and the critical sleep fix.
#
# Run from the Sub-C2 repo root on Kali:
#   chmod +x apply-sleep-fix.sh && ./apply-sleep-fix.sh

set -euo pipefail
cd "$(git rev-parse --show-toplevel 2>/dev/null || pwd)"

PATCH_B64=''

echo "$PATCH_B64" | base64 -d | git apply --check 2>&1
if [ $? -ne 0 ]; then
    echo "⚠  Patch does not apply cleanly — your tree may already have some changes."
    echo "   Trying with --3way..."
    echo "$PATCH_B64" | base64 -d | git apply --3way 2>&1
else
    echo "$PATCH_B64" | base64 -d | git apply
    echo "✅ Patch applied successfully."
fi

echo ""
echo "Files changed:"
echo "  oxide-agent/src/beacon.rs        — pre-registration sleep now uses plain tokio sleep (bypasses Ekko crash)"
echo "  oxide-agent/src/evasion/sleep_mask.rs — catch_unwind around Ekko/Foliage/Zilean with fallback to plain sleep"
echo "  oxide-agent/src/main.rs          — panic hook + extended debug logging"
echo "  oxide-agent/src/comms/http.rs     — HTTP request/response debug logging"
echo "  oxide-agent/src/evasion/sandbox.rs — per-check debug logging"
echo "  oxide-server/src/listeners/http.rs — 50MB body limit for screenshots"
echo ""
echo "Now commit and rebuild:"
echo "  git add -A && git commit -m 'fix: bypass obfuscated sleep for pre-registration + catch_unwind safety net'"
echo ""
echo "Then in the TUI, build a new payload and transfer it to Windows."
echo "After running it, check debug log:  type \$env:TEMP\\oxide_debug.txt"
